	public static string DescribeFileSource(string path)
	{
		if (string.IsNullOrEmpty(path))
		{
			return path;
		}
		try
		{
			if (!Singleton<FileManager>.InstanceExists())
			{
				return path;
			}
			string modSourceForFile = Singleton<FileManager>.Instance.GetModSourceForFile(Path.GetFullPath(path));
			if (string.IsNullOrEmpty(modSourceForFile))
			{
				return path;
			}
			return path + " (from mod '" + modSourceForFile + "')";
		}
		catch
		{
			return path;
		}
	}

