	private static string NormalizeRelative(string path)
	{
		path = path.Replace('\\', '/');
		while (path.Contains("//"))
		{
			path = path.Replace("//", "/");
		}
		return path.TrimStart('/');
	}

	private bool IsIndexable(DirectoryInfo directory)
	{
		return !PathEquals(directory.FullName, specialDirectories[0].FullName);
	}

	private HashSet<string> IndexFor(DirectoryInfo directory)
	{
		return _fileIndex.GetOrAdd(directory.FullName, (string root) =>
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			try
			{
				foreach (string item in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
				{
					hashSet.Add(NormalizeRelative(Path.GetRelativePath(root, item)));
				}
			}
			catch (Exception ex)
			{
				Log.Warning("FileManager: could not index '" + root + "': " + ex.Message, Log.Section.General, "E:\\projects\\seapower\\Assets\\Scripts\\FileManager.cs", 675, "IndexFor");
			}
			return hashSet;
		});
	}

	private bool FileExistsIn(DirectoryInfo directory, string relativePath, string fullPath)
	{
		if (Path.IsPathRooted(relativePath) || !IsIndexable(directory) || !directory.Exists)
		{
			return File.Exists(fullPath);
		}
		return IndexFor(directory).Contains(NormalizeRelative(relativePath));
	}

