			return string.Empty;
		}
		string text = NormalizePath(specialDirectories[1].FullName);
		for (int i = 0; i < Directories.Count; i++)
		{
			if (!Directories[i].IsChecked)
			{
				continue;
			}
			string relativePath = Path.GetRelativePath(Directories[i].DirectoryInfo.FullName, fullPath);
			if (!relativePath.StartsWith("..") && !Path.IsPathRooted(relativePath))
			{
				if (NormalizePath(Directories[i].DirectoryInfo.FullName) == text)
				{
					return string.Empty;
				}
				return Directories[i].Name ?? string.Empty;
			}
		}
		return string.Empty;
	}

	public string GetRelativePath(string path)
	{
		if (string.IsNullOrEmpty(path))
		{
			return null;
		}
		DirectoryInfo potentialDescendant = new DirectoryInfo(path);
		for (int i = 0; i < Directories.Count; i++)
		{
			if (IsDescendantOf(Directories[i].DirectoryInfo, potentialDescendant))
			{
				if (!Directories[i].IsChecked)
				{
					Debug.LogWarning("FileManager.GetRelativePath(" + path + ") is using a top level folder that is not selected for use in game!");
				}
				return Path.GetRelativePath(Directories[i].DirectoryInfo.FullName, path);
			}
		}
		return null;
	}

