namespace SeaPowerFileIndexFix
{
    // Diagnoses (and optionally works around) FileManager's cached file index, which was
    // introduced after 0.8.2 and makes base-game files unresolvable under CrossOver/Wine.
    [BepInPlugin("local.seapower.fileindexfix", "Sea Power File Index Fix", "1.0.0")]
    public class Plugin : BaseUnityPlugin
    {
        internal static ManualLogSource Log;
        internal static ConfigEntry<bool> UseFileExists;
        internal static ConfigEntry<int> MaxLoggedLookups;

        private void Awake()
        {
            Log = Logger;
            UseFileExists = Config.Bind("Fix", "UseFileExistsInsteadOfIndex", false,
                "When true, FileManager checks every mod folder with File.Exists (the 0.8.2 behaviour) instead of the cached index.");
            MaxLoggedLookups = Config.Bind("Diagnostics", "MaxLoggedLookups", 60,
                "How many individual file lookups to log in detail.");

            Log.LogInfo($"streamingAssetsPath = '{Application.streamingAssetsPath}'");
            Log.LogInfo($"Fix enabled (UseFileExistsInsteadOfIndex) = {UseFileExists.Value}");
            new Harmony("local.seapower.fileindexfix").PatchAll(typeof(Plugin).Assembly);
            Log.LogInfo("Patches applied.");
        }
    }

    [HarmonyPatch(typeof(FileManager), "IndexFor")]
    internal static class IndexForPatch
    {
        private static readonly ConcurrentDictionary<string, bool> Logged = new ConcurrentDictionary<string, bool>(StringComparer.OrdinalIgnoreCase);

        private static void Postfix(DirectoryInfo directory, HashSet<string> __result)
        {
            if (!Logged.TryAdd(directory.FullName, true))
            {
                return;
            }
            int count = __result?.Count ?? -1;
            Plugin.Log.LogInfo($"IndexFor('{directory.FullName}'): {count} entries");
            if (__result != null)
            {
                foreach (string entry in __result.Take(8))
                {
                    Plugin.Log.LogInfo($"  index entry: '{entry}'");
                }
                Plugin.Log.LogInfo($"  contains 'vessels/usn_ssn_los_angeles.ini' = {__result.Contains("vessels/usn_ssn_los_angeles.ini")}");
            }
            try
            {
                int direct = Directory.EnumerateFiles(directory.FullName, "*", SearchOption.AllDirectories).Count();
                Plugin.Log.LogInfo($"  direct re-enumeration now finds {direct} files");
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"  direct re-enumeration threw {ex.GetType().Name}: {ex.Message}");
            }
        }
    }

    [HarmonyPatch(typeof(FileManager), "FileExistsIn")]
    internal static class FileExistsInPatch
    {
        private static int _logged;

        private static bool Prefix(string fullPath, ref bool __result)
        {
            if (!Plugin.UseFileExists.Value)
            {
                return true;
            }
            __result = File.Exists(fullPath);
            return false;
        }

        private static void Postfix(FileManager __instance, DirectoryInfo directory, string relativePath, string fullPath, bool __result)
        {
            if (Interlocked.Increment(ref _logged) > Plugin.MaxLoggedLookups.Value)
            {
                return;
            }
            bool isUser = FileManager.PathEquals(directory.FullName, __instance.specialDirectories[0].FullName);
            Plugin.Log.LogInfo($"FileExistsIn(dir='{directory.FullName}', rel='{relativePath}') -> {__result}; isUserDir={isUser}; File.Exists(full)={File.Exists(fullPath)}; full='{fullPath}'; thread={Thread.CurrentThread.ManagedThreadId}");
        }
    }

    [HarmonyPatch(typeof(FileManager), nameof(FileManager.GetFile))]
    internal static class GetFilePatch
    {
        private static int _logged;

        private static void Postfix(string path, string __result)
        {
            if (Interlocked.Increment(ref _logged) > Plugin.MaxLoggedLookups.Value)
            {
                return;
            }
            Plugin.Log.LogInfo($"GetFile('{path}') -> '{__result ?? "<null>"}'");
        }
    }
}

