            }
            else if (n % 1000 == 0)
            {
                Plugin.Log.LogWarning($"ReadFileToIni on missing user paths: {n} so far");
            }
        }
    }

    [HarmonyPatch(typeof(IniHandler), nameof(IniHandler.open))]
    internal static class OpenPatch
    {
        private static int _userOpens;

        private static void Prefix(string path)
        {
            if (UserPath.IsUnderUser(path) && !File.Exists(path) && Interlocked.Increment(ref _userOpens) <= 5)
            {
