private static readonly object Gate = new object();
private static int _rejected;

// Mirrors FileManager.FileExistsIn, but routes the File.Exists branch through SafeExists.
private static bool Prefix(FileManager __instance, DirectoryInfo directory, string relativePath, string fullPath, ref bool __result)
{
    if (!Plugin.VerifyFileExists.Value)
    {
        return true;
    }
    bool isUser = FileManager.PathEquals(directory.FullName, __instance.specialDirectories[0].FullName);
    if (Path.IsPathRooted(relativePath) || isUser || !directory.Exists)
    {
        __result = SafeExists(fullPath);
        return false;
    }
    return true;
}

// Under CrossOver/Wine, File.Exists has been observed to return true for missing files when
// called from the parallel unit loader's worker threads, so a positive answer is confirmed
// against a directory listing before it is trusted.
private static bool SafeExists(string fullPath)
{
    bool exists;
    lock (Gate)
    {
        exists = File.Exists(fullPath);
    }
    if (!exists)
    {
        return false;
    }
    bool confirmed;
    try
    {
        string dir = Path.GetDirectoryName(fullPath);
        string name = Path.GetFileName(fullPath);
        confirmed = Directory.Exists(dir) && Directory.EnumerateFiles(dir, name).Any();
    }
    catch (Exception)
    {
        confirmed = false;
    }
    if (!confirmed)
    {
        int n = Interlocked.Increment(ref _rejected);
        if (n <= 5 || n % 500 == 0)
        {
            Plugin.Log.LogWarning($"Rejected false File.Exists for '{fullPath}' on thread {Thread.CurrentThread.ManagedThreadId} ({n} rejected so far)");
        }
    }
    return confirmed;
}

